/bin/bash -lc 'catalogue_dir=$(find "$TMPDIR" -maxdepth 1 -type d -name '"'amar-singh-catalogue.*' -print | tail -1); python3 -c 'from bs4 import BeautifulSoup; from pathlib import Path; import re,sys; d=Path(sys.argv[1]);
for n in (1,2,5):
 p=d/f\"page-{n}.html\"; s=BeautifulSoup(p.read_text(errors=\"replace\"),\"html.parser\"); print(f\"--- page-{n} TITLE={s.title.get_text(\" \",strip=True) if s.title else \"\"} ---\");
 for i,t in enumerate(s.find_all(\"table\")):
  print(f\"TABLE {i+1}\");
  for tr in t.find_all(\"tr\"):
   cells=[re.sub(r\"\\\\s+\",\" \",c.get_text(\" \",strip=True)) for c in tr.find_all([\"th\",\"td\"])]
   if cells: print(\" | \".join(cells))
 for h in s.find_all([\"h1\",\"h2\",\"h3\"]):
  x=re.sub(r\"\\\\s+\",\" \",h.get_text(\" \",strip=True));
  if x: print(\"HEADING\",x)
' \""'$catalogue_dir"'

