/bin/bash -lc "db='assets/data/career_path.db'; python3 -c 'import sqlite3,sys; db=sys.argv[1]; con=sqlite3.connect(db); rows={r[0]:r for r in con.execute(\"select id,slug,name,parent_id,stream_id from career_nodes\")}; ids=[30,71,79,341,344,165,166,167,365,378,52,72,79,341,344];
for i in ids:
 if i not in rows: continue
 chain=[]; cur=i; seen=set()
 while cur is not None and cur not in seen:
  seen.add(cur); r=rows[cur]; chain.append(\"{}:{} ({})\".format(r[0],r[1],r[2])); cur=r[3]
 print(\"NODE\",i,\" -> \",\" > \".join(reversed(chain)))
' \""'$db"'

